import  { DatepickerDate, DatepickerViews,DatepickerLocale } from '../Default';

import consts from './consts';

/**
 * Types & Interfaces
 */
export interface ParsedDate {
    date: number;
    hours: number;
    fullDate: string | any;
    month: number;
    fullHours: string | any;
    year: number;
    minutes: number;
    fullMonth: string | any;
    day: number;
    fullMinutes: string | any; 
    hours12: number;
    dayPeriod: 'am' | 'pm';
    fullHours12: string | any;
}

export interface DayPeriod {
    dayPeriod: 'am' | 'pm';
    hours: number;
}

type ClassNamesArg = string | Record<string, any> | undefined | null | false;

/**
 * Finds DOM element
 */
export function getEl(el: string | HTMLElement, context: Document | HTMLElement = document): HTMLElement | null {
    return typeof el === 'string'
        ? context.querySelector(el)
        : el;
}

/**
 * Creates HTML DOM element
 */
interface CreateElementOptions {
    tagName?: string;
    className?: string;
    innerHtml?: string;
    id?: string;
    attrs?: Record<string, any>;
}

export function createElement({
    tagName = 'div',
    className = '',
    innerHtml = '',
    id = '',
    attrs = {}
}: CreateElementOptions = {}): HTMLElement {
    const $element = document.createElement(tagName);
    if (className) $element.classList.add(...className.split(' ').filter(Boolean));
    if (id) $element.id = id;

    if (innerHtml) {
        $element.innerHTML = innerHtml;
    }

    if (attrs) {
        setAttribute($element, attrs);
    }

    return $element;
}

/**
 * Sets multiple attributes of element
 */
export function setAttribute(el: HTMLElement, attrs: Record<string, any>): HTMLElement {
    for (const [name, value] of Object.entries(attrs)) {
        if (value === undefined) continue;
        el.setAttribute(name, String(value));
    }
    return el;
}

/**
 * Inserts newElement after targetElement
 */
export function insertAfter(newElement: HTMLElement, targetElement: HTMLElement): HTMLElement {
    targetElement.parentNode?.insertBefore(newElement, targetElement.nextSibling);
    return newElement;
}

/**
 * Makes object deep copy
 */
export function deepCopy<T>(obj: T): T {
    return JSON.parse(JSON.stringify(obj));
}

/**
 * Calculates amount of days in passed date
 */
export function getDaysCount(date: Date): number {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
}

/**
 * Get detailed date object
 */
export function getParsedDate(date: Date): ParsedDate {
    const hours = date.getHours();
    const { hours: hours12, dayPeriod } = getDayPeriodFromHours24(hours);
    const month = date.getMonth();
    const dayOfMonth = date.getDate();
    const minutes = date.getMinutes();

    return {
        year: date.getFullYear(),
        month,
        fullMonth: (month + 1) < 10 ? '0' + (month + 1) : month + 1,
        date: dayOfMonth,
        fullDate: dayOfMonth < 10 ? '0' + dayOfMonth : dayOfMonth,
        day: date.getDay(),
        hours,
        fullHours: getLeadingZeroNum(hours),
        hours12,
        dayPeriod,
        fullHours12: getLeadingZeroNum(hours12),
        minutes,
        fullMinutes: minutes < 10 ? '0' + minutes : minutes
    };
}

export function getDayPeriodFromHours24(hours: number): DayPeriod {
    const hours12 = hours % 12 === 0 ? 12 : hours % 12;
    const dayPeriod = hours > 11 ? 'pm' : 'am';

    return {
        dayPeriod,
        hours: hours12
    };
}

/**
 * Converts 1 -> 01
 */
export function getLeadingZeroNum(num: number): string | number {
    return num < 10 ? '0' + num : num;
}

/**
 * Calculates current decade
 */
export function getDecade(date: Date) {
    let firstYear = Math.floor(date.getFullYear() / 10) * 10;
    return [firstYear, firstYear + 9];
}

/**
 * Subtract days from date
 */
export function subDays(date: Date, days: number): Date {
    const { year, month, date: _date } = getParsedDate(date);
    return new Date(year, month, _date - days);
}

/**
 * Class names' handler
 */
export function classNames(...classes: ClassNamesArg[]): string {
    const result: string[] = [];

    classes.forEach((c) => {
        if (!c) return;
        if (typeof c === 'object') {
            for (const cName in c) {
                if (c[cName]) {
                    result.push(cName);
                }
            }
        } else {
            result.push(c);
        }
    });
    return result.join(' ');
}

export function toggleClass(el: HTMLElement, classes: Record<string, boolean>): void {
    for (const className in classes) {
        if (classes[className]) {
            el.classList.add(className);
        } else {
            el.classList.remove(className);
        }
    }
}

export function addClass(el: HTMLElement | NodeListOf<Element> | Element[], ...classes: string[]): void {
    if (el instanceof NodeList || Array.isArray(el)) {
        el.forEach((node) => {
            if (node instanceof Element) node.classList.add(...classes);
        });
    } else {
        el.classList.add(...classes);
    }
}

export function removeClass(el: HTMLElement | NodeListOf<Element> | Element[], ...classes: string[]): void {
    if (el instanceof NodeList || Array.isArray(el)) {
        el.forEach((node) => {
            if (node instanceof Element) node.classList.remove(...classes);
        });
    } else {
        el.classList.remove(...classes);
    }
}

/**
 * Checks if passed dates are the same
 */
// Define allowed view types for stricter checks
    type CalendarViewType = typeof consts.days | typeof consts.months | typeof consts.years;

    export function isSameDate(
        date1: DatepickerDate | undefined | null, 
        date2: DatepickerDate | undefined | null, 
        cellType: CalendarViewType = consts.days
    ): boolean {
        // 1. Convert inputs to Date objects safely
        const d1Obj = date1 ? createDate(date1) : false;
        const d2Obj = date2 ? createDate(date2) : false;

        // 2. If either conversion failed, they aren't the same valid date
        if (!(d1Obj instanceof Date) || !(d2Obj instanceof Date)) {
            return false;
        }

        const d1 = getParsedDate(d1Obj);
        const d2 = getParsedDate(d2Obj);

        // 3. Logic Mapping
        const conditions = {
            [consts.days]: d1.date === d2.date && d1.month === d2.month && d1.year === d2.year,
            [consts.months]: d1.month === d2.month && d1.year === d2.year,
            [consts.years]: d1.year === d2.year
        };

        return conditions[cellType];
}
