export function isDateBigger(date: Date, comparedDate: Date, loose?: boolean): boolean {
    const d1 = copyDate(date, false).getTime();
    const d2 = copyDate(comparedDate, false).getTime();

    return loose ? d1 >= d2 : d1 > d2;
}

export function isDateSmaller(date: Date, comparedDate: Date): boolean {
    return !isDateBigger(date, comparedDate, true);
}

/**
 * Copies date
 */
export function copyDate(date: Date, keepTime: boolean = true): Date {
    const newDate = new Date(date.getTime());

    if (!keepTime) {
        resetTime(newDate);
    }

    return newDate;
}

export function resetTime(date: Date): Date {
    date.setHours(0, 0, 0, 0);
    return date;
}

export function isDateBetween(date: Date, dateFrom: Date, dateTo: Date): boolean {
    return isDateBigger(date, dateFrom) && isDateSmaller(date, dateTo);
}

/**
 * Adds event listener to DOM element
 */
export function addEventListener(
    el: HTMLElement | NodeListOf<Element> | Element[], 
    type: string, 
    listener: EventListenerOrEventListenerObject
): void {
    if (el instanceof NodeList || Array.isArray(el)) {
        el.forEach((e) => {
            e.addEventListener(type, listener);
        });
    } else {
        el.addEventListener(type, listener);
    }
}

/**
 * Finds closest DOM element
 */
export function closest(target: HTMLElement | ParentNode | null, selector: string): HTMLElement | false {
    if (!target || target === document || target instanceof DocumentFragment) return false;

    if ((target as HTMLElement).matches(selector)) {
        return target as HTMLElement;
    }

    return closest(target.parentNode, selector);
}

/**
 * Clamps number
 */
export function clamp(val: number, min: number, max: number): number {
    return val > max ? max : val < min ? min : val;
}

export function deepMerge<T extends Record<string, any>>(target: T, ...objects: (Record<string, any> | undefined)[]): T {
    objects.filter(Boolean).forEach((obj) => {
        if (!obj) return;
        for (const [key, value] of Object.entries(obj)) {
            // Check if it's a "plain" object or array
            // Date, RegExp, etc. should be treated as primitives during a merge
            const isObject = value !== null && typeof value === 'object';
            const isDate = value instanceof Date;
            const isRegExp = value instanceof RegExp;

            if (isObject && !isDate && !isRegExp) {
                const targetValue = target[key];
                const initialValue = Array.isArray(value) ? [] : {};

                if (!targetValue || typeof targetValue !== 'object') {
                    (target as any)[key] = initialValue;
                }

                deepMerge(target[key], value);
            } else {
                // For Dates and primitives, just assign directly
                (target as any)[key] = value;
            }
        }
    });

    return target;
}

function dateStringIsDateOnly(dateString: string): boolean {
    return /^\d{4}-\d{2}-\d{2}$/.test(dateString);
}

/**
 * Creates Date object
 */
/**
 * utils.ts
 * Converts various inputs into a valid Date object.
 * Designed to handle Storybook control edge-cases.
 */
    export function createDate(date: DatepickerDate): Date | false {
        let resultDate: Date;

        if (date instanceof Date) {
            // console.log('createDate ' + date);
            resultDate = date;
        } else {
            let dateValue: string | number = date;
            // console.log('dateValue ' + dateValue);
            if (typeof dateValue === 'string' && dateStringIsDateOnly(dateValue)) {
                dateValue += 'T00:00:00';
            }
            
            resultDate = new Date(dateValue);
            // console.log('dateValue resultDate ' + resultDate);
        }

        if (isNaN(resultDate.getTime())) {
            return false;
        }

        return resultDate;
    }

export function getTimeRegExp(sign: string): RegExp {
    let symbols = '\\s|\\.|-|/|\\\\|,|\\$|\\!|\\?|:|;';

    return new RegExp('(^|>|' + symbols + ')(' + sign + ')($|<|' + symbols + ')', 'g');
}

export function template(str: string, replacer: (match: string) => string): string {
    // This regex looks for word boundaries or specific patterns
    // Depending on your implementation, it might look like /([a-zA-Z]+)/g
    return str.replace(/[a-z0-9_]+/gi, (match) => {
        return replacer(match);
    });
}

export function getWordBoundaryRegExp(sign: string) {
    let symbols = '\\s|\\.|-|/|\\\\|,|\\$|\\!|\\?|:|;';

    return new RegExp('(^|>|' + symbols + ')(' + sign + ')($|<|' + symbols + ')', 'g');
}